NOTE_BASE = {
    'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5,
    'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11
}

def N(name):
    name = name.strip()
    if name in ('off', 'OFF', '==='):
        return 97
    if len(name) >= 3 and name[1] in '#b':
        lit, octv = name[:2], int(name[2:])
    else:
        lit, octv = name[0], int(name[1:])
        if name[1] == '-':
            octv = int(name[2:])
    # C-4 = 49 => 12*4 + 0 + 1 = 49
    return 12 * octv + NOTE_BASE[lit] + 1

for s in ['C-4','A-2','E-5','C-7','G-3','F-2','B-4','A#4','D#5']:
    print(s, N(s))
PY"}

