{"command":"python3 << 'PY'
import json

# Effect 8 = set panning, param 0 left .. 255 right
calls = []
def pan(p, row, ch, val):
    calls.append({"name":"pattern_set_cell","arguments":{
        "pattern":p,"row":row,"channel":ch,"effect":8,"effect_param":val
    }})

# For every pattern, set pans on row 0 (and keep instruments going)
# ch0 kick center, ch1 snare slight R, ch2 hats R, ch3 bass C,
# ch4 arp R, ch5 lead L, ch6 pad L, ch7 chip/bell R
PANS = [0x80, 0x90, 0xB0, 0x80, 0xC0, 0x60, 0x50, 0xD0]
for p in range(12):
    for ch, val in enumerate(PANS):
        pan(p, 0, ch, val)

# Also add subtle pan slide / width on arp and lead mid-pattern for motion
for p in [2,3,4,5,7,8,9,11]:
    # lead pan drift
    calls.append({"name":"pattern_set_cell","arguments":{
        "pattern":p,"row":32,"channel":5,"effect":8,"effect_param":0x70
    }})
    calls.append({"name":"pattern_set_cell","arguments":{
        "pattern":p,"row":48,"channel":4,"effect":8,"effect_param":0xA0
    }})

with open('/workspace/pan_batch.json','w') as f:
    json.dump(calls, f)
print(len(calls))
PY
ft2 batch /workspace/pan_batch.json 2>&1 | tail -5

